def route_request(prompt: str, classifier) -> str:
    complexity = classifier.predict_proba(prompt)
    if complexity < 0.35:
        return "qwen-2.5-7b-instruct"   # rápido y económico
    if "sql" in prompt.lower() or complexity > 0.8:
        return "llama-3.1-70b-instruct"
    return "qwen-2.5-32b-instruct"
